<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Conway's Game of Life</title>
<style>
  :root {
    --bg: #0a0e1a;
    --panel: #131a2c;
    --accent: #ff5ea8;
    --accent2: #5effc8;
    --text: #e8eefc;
    --dim: #6b7896;
    --grid-line: rgba(94, 255, 200, 0.08);
    --cell: #5effc8;
    --cell-glow: rgba(94, 255, 200, 0.55);
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  html, body { height: 100%; }
  body {
    background: radial-gradient(ellipse at 20% 10%, #1a2342 0%, transparent 50%),
                radial-gradient(ellipse at 80% 90%, #2a1330 0%, transparent 55%),
                var(--bg);
    color: var(--text);
    font-family: 'Trebuchet MS', 'Segoe UI', system-ui, sans-serif;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 24px;
    overflow: hidden;
  }
  h1 {
    font-size: clamp(28px, 4vw, 44px);
    letter-spacing: 2px;
    margin-bottom: 4px;
    background: linear-gradient(90deg, var(--accent), var(--accent2));
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
    text-shadow: 0 0 30px rgba(255, 94, 168, 0.2);
  }
  .subtitle { color: var(--dim); font-size: 14px; margin-bottom: 18px; }
  .stage {
    background: linear-gradient(180deg, var(--panel), #0d1322);
    border: 1px solid rgba(255, 255, 255, 0.06);
    border-radius: 18px;
    padding: 22px;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.04);
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 16px;
  }
  #life {
    display: block;
    border-radius: 10px;
    background: #060912;
    cursor: crosshair;
    touch-action: none;
    box-shadow: inset 0 0 40px rgba(0,0,0,0.6);
  }
  .controls {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    justify-content: center;
    align-items: center;
  }
  button {
    appearance: none;
    border: 1px solid rgba(255, 255, 255, 0.1);
    background: linear-gradient(180deg, #1d2740, #141b30);
    color: var(--text);
    padding: 10px 18px;
    border-radius: 999px;
    font-size: 14px;
    font-weight: 600;
    letter-spacing: 0.5px;
    cursor: pointer;
    transition: transform 0.12s ease, box-shadow 0.12s ease, background 0.2s ease;
    user-select: none;
    min-width: 96px;
  }
  button:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.4), 0 0 0 1px var(--accent2);
    background: linear-gradient(180deg, #243056, #18203a);
  }
  button:active { transform: translateY(0) scale(0.97); }
  #play.playing {
    background: linear-gradient(180deg, var(--accent), #c84590);
    color: #fff;
    box-shadow: 0 0 22px rgba(255, 94, 168, 0.5);
  }
  .stats {
    display: flex;
    gap: 22px;
    font-size: 13px;
    color: var(--dim);
  }
  .stats b { color: var(--accent2); font-weight: 700; }
  .hint { color: var(--dim); font-size: 12px; }
  @media (max-width: 500px) {
